Let $\mathcal{E}$ be a Euclidean vector space, $C$ a nonempty closed subset of $\mathcal{E}$, and $f : \mathcal{E} \to \R$ a function satisfying at least the first of the following two properties:
\begin{enumerate}[label={(H\arabic*)}]
\item $f$ is differentiable on $C$, i.e., for every $x \in C$, there exists a (unique) vector in $\mathcal{E}$, denoted by $\nabla f(x)$, such that
\begin{equation*}
\lim_{\substack{y \to x \\ y \in \mathcal{E} \setminus \{x\}}} \frac{f(y)-f(x)-\ip{\nabla f(x)}{y-x}}{\norm{y-x}} = 0,
\end{equation*}
and $\nabla f : C \to \mathcal{E}$ is continuous;
\label{it:continuously_diff}
\item $f$ is differentiable on $\mathcal{E}$ and $\nabla f : \mathcal{E} \to \mathcal{E}$ is locally Lipschitz continuous.
\label{it:Lipschitz_diff}
\end{enumerate}
This paper considers the problem
\begin{equation}
\label{eq:MinDiffFunctionClosedSet}
\min_{x \in C} f(x)
\end{equation}
of minimizing $f$ on~$C$.


A point $x \in C$ is said to be stationary for~\eqref{eq:MinDiffFunctionClosedSet} if $-\nabla f(x)$ is normal to $C$ at~$x$. Several definitions of normality exist. Each defines a different notion of stationarity, which is a surrogate for local optimality in the sense that, possibly under mild regularity assumptions on~$f$, every local minimizer of $f|_C$ is stationary for~\eqref{eq:MinDiffFunctionClosedSet}. In particular, each of the three notions of normality in \cite[Definition~6.3 and Example~6.16]{RockafellarWets}, namely normality in the general sense, in the regular sense, and in the proximal sense, yields an important definition of stationarity. The sets of general, regular, and proximal normals to $C$ at $x \in C$ are respectively denoted by $\norcone{C}{x}$, $\regnorcone{C}{x}$, and $\proxnorcone{C}{x}$. These sets are reviewed in section~\ref{subsec:NormalityStationarity}. Importantly, they are nested as follows: for every $x \in C$,
\begin{equation}
\label{eq:NestedNormalCones}
\proxnorcone{C}{x} \subseteq \regnorcone{C}{x} \subseteq \norcone{C}{x},
\end{equation}
and $C$ is said to be \emph{Clarke regular} at $x$ if the second inclusion is an equality.


\begin{definition}
\label{def:M/B/P-Stationarity}
For problem~\eqref{eq:MinDiffFunctionClosedSet}, a point $x \in C$ is said to be:
\begin{itemize}
\item \emph{Mordukhovich stationary (M-stationary)} if $-\nabla f(x) \in \norcone{C}{x}$;
\item \emph{Bouligand stationary (B-stationary)} if $-\nabla f(x) \in \regnorcone{C}{x}$;
\item \emph{proximally stationary (P-stationary)} if $-\nabla f(x) \in \proxnorcone{C}{x}$.
\end{itemize}
\end{definition}


Monotone $\pgd$ accumulates at M-stationary points of~\eqref{eq:MinDiffFunctionClosedSet} if $f$ is continuously differentiable on~$\mathcal{E}$ and bounded from below on~$C$ \cite[Theorem~3.1]{KanzowMehlitz}. The same result holds for nonmonotone $\pgd$ with the ``average'' rule \cite[Theorem~4.6]{DeMarchi}, and also for nonmonotone $\pgd$ with the ``max'' rule if $f$ is further uniformly continuous on the sublevel set
\begin{equation}
\label{eq:InitialSublevelSet}
\{x \in C \mid f(x) \le f(x_0)\},
\end{equation}
where $x_0 \in C$ is the initial iterate given to the algorithm \cite[Theorem~4.1]{KanzowMehlitz}.


Recall that, throughout the paper, $\mathcal{E}$ is a Euclidean vector space and $C \subseteq \mathcal{E}$ is nonempty and closed. Moreover, for every $x \in \mathcal{E}$ and $\rho \in (0, \infty)$, $\ball(x, \rho) \coloneq \{y \in \mathcal{E} \mid \norm{x-y} < \rho\}$ and $\ball[x, \rho] \coloneq \{y \in \mathcal{E} \mid \norm{x-y} \le \rho\}$ are respectively the open and closed balls of center $x$ and radius $\rho$ in~$\mathcal{E}$.
A nonempty subset $K$ of $\mathcal{E}$ is called a \emph{cone} if $x \in K$ implies $\alpha x \in K$ for all $\alpha \in [0, \infty)$ \cite[\S 3B]{RockafellarWets}.


Given $x \in \mathcal{E}$, the distance from $x$ to $C$ is $\dist(x, C) \coloneq \min_{y \in C} \norm{x-y}$ and the projection of $x$ onto $C$ is $\proj{C}{x} \coloneq \argmin_{y \in C} \norm{x-y}$. The function $\mathcal{E} \to \R : x \mapsto \dist(x, C)$ is continuous and, for every $x \in \mathcal{E}$, the set $\proj{C}{x}$ is nonempty and compact \cite[Example~1.20]{RockafellarWets}.
Proposition~\ref{prop:ProjectedTranslation} is invoked frequently in the rest of the paper.


A vector $v \in \mathcal{E}$ is said to be \emph{tangent} to $C$ at $x \in C$ if there exist sequences $(x_i)_{i \in \N}$ in $C$ converging to $x$ and $(t_i)_{i \in \N}$ in $(0, \infty)$ such that the sequence $(\frac{x_i-x}{t_i})_{i \in \N}$ converges to $v$ \cite[Definition~6.1]{RockafellarWets}. The set of all tangent vectors to $C$ at $x \in C$ is a closed cone \cite[Proposition~6.2]{RockafellarWets} called the \emph{tangent cone} to $C$ at $x$ and denoted by $\tancone{C}{x}$.
The \emph{regular normal cone} to $C$ at $x \in C$ is
\begin{equation*}
\regnorcone{C}{x} \coloneq \left\{v \in \mathcal{E} \mid \ip{v}{w} \le 0 \; \forall w \in \tancone{C}{x}\right\},
\end{equation*}
which is a closed convex cone \cite[Definition~6.3 and Proposition~6.5]{RockafellarWets}.
A vector $v \in \mathcal{E}$ is said to be \emph{normal (in the general sense)} to $C$ at $x \in C$ if there exist sequences $(x_i)_{i \in \N}$ in $C$ converging to $x$ and $(v_i)_{i \in \N}$ converging to $v$ such that, for all $i \in \N$, $v_i \in \regnorcone{C}{x_i}$ \cite[Definition~6.3]{RockafellarWets}. The set of all normal vectors to $C$ at $x \in C$ is a closed cone \cite[Proposition~6.5]{RockafellarWets} called the \emph{normal cone} to $C$ at $x$ and denoted by $\norcone{C}{x}$.
A vector $v \in \mathcal{E}$ is called a \emph{proximal normal} to $C$ at $x \in C$ if there exists $\oshort{\alpha} \in (0, \infty)$ such that $x \in \proj{C}{x+\oshort{\alpha}v}$, i.e., $\oshort{\alpha}\norm{v} = \dist(x+\oshort{\alpha}v, C)$, which implies that, for all $\alpha \in [0, \oshort{\alpha})$, $\proj{C}{x+\alpha v} = \{x\}$ \cite[Example~6.16]{RockafellarWets}. The set of all proximal normals to $C$ at $x \in C$ is a convex cone called the \emph{proximal normal cone} to $C$ at $x$ and denoted by $\proxnorcone{C}{x}$.


\begin{algorithm}[H]
\caption{$\pgd$ map}
\label{algo:PGDmap}
\begin{algorithmic}[1]
\Require
$(\mathcal{E}, C, f, \ushort{\alpha}, \oshort{\alpha}, \beta, c)$, where $\mathcal{E}$ is a Euclidean vector space, $C$ is a nonempty closed subset of~$\mathcal{E}$, $f : \mathcal{E} \to \R$ satisfies \ref{it:continuously_diff}, $0 < \ushort{\alpha} \le \oshort{\alpha} < \infty$, and $\beta, c \in (0, 1)$.
\Input
$(x, \mu)$ with $x \in C$ and $\mu \in [f(x), \infty)$.
\Output
$y \in \pgd(x, \mu; \mathcal{E}, C, f, \ushort{\alpha}, \oshort{\alpha}, \beta, c)$.

\State
Choose $\alpha \in [\ushort{\alpha}, \oshort{\alpha}]$ and $y \in \proj{C}{x-\alpha\nabla f(x)}$;
\label{algo:PGDmap:InitialStepSize}
\While
{$f(y) > \mu + c \ip{\nabla f(x)}{y-x}$}
\label{algo:PGDmap:NonmonotoneArmijoCondition}
\State
$\alpha \gets \alpha \beta$;
\State
Choose $y \in \proj{C}{x-\alpha\nabla f(x)}$;
\EndWhile
\State
Return $y$.
\end{algorithmic}
\end{algorithm}


\begin{remark}
The Armijo condition
\begin{equation*}
f(y) \le \mu + c \ip{\nabla f(x)}{y-x}
\end{equation*}
ensures that the decrease $\mu-f(y)$ is at least a fraction $c$ of the opposite of the directional derivative of $f$ at $x$ along the update vector $y-x$. By \eqref{eq:ProjectedTranslationIP}, this condition implies that
\begin{equation}\label{eq:KanzowMehlitzDecay}
f(y) \le \mu - \frac{c}{2\alpha} \norm{y-x}^2,
\end{equation}
which is the condition used in \cite[Algorithms~3.1 and 4.1]{KanzowMehlitz} and \cite[Algorithm~3.1]{DeMarchi}. Importantly, all results from \cite{KanzowMehlitz} hold for both conditions, as is clear from the proofs.
% Par contre, les résultats de De Marchi ne sont pas clairement valides avec notre condition (je pense au lemme 4.4).
\end{remark}


The $\pgd$ algorithm is defined as Algorithm~\ref{algo:PGD}. It is said to be monotone or nonmonotone depending on whether $\mu_i=f(x_i)$ for all $i$ (that is, $l=0$ for the ``max'' rule, or $p=1$ for the ``average'' rule) or not.

\begin{algorithm}[H]
\caption{$\pgd$}
\label{algo:PGD}
\begin{algorithmic}[1]
\Require
$(\mathcal{E}, C, f, \ushort{\alpha}, \oshort{\alpha}, \beta, c, \text{``nonmonotonicity''})$, where $\mathcal{E}$ is a Euclidean vector space, $C$ is a nonempty closed subset of~$\mathcal{E}$, $f : \mathcal{E} \to \R$ satisfies \ref{it:continuously_diff}, $0 < \ushort{\alpha} \le \oshort{\alpha} < \infty$, $\beta, c \in (0, 1)$, and $\text{``nonmonotonicity''} \in \{(\text{``max''}, l), (\text{``average''}, p)\}$ with $l \in \N$ and $p \in (0, 1]$.
\Input
$x_0 \in C$.
\Output
a sequence in $C$.

\State
$i \gets 0$;
\State
$\mu_{-1} \gets f(x_0)$;
\While
{$-\nabla f(x_i) \notin \regnorcone{C}{x_i}$}
\label{algo:PGD:while}
\If
{$\text{``nonmonotonicity''} = (\text{``max''}, l)$}
\State
$\mu_i \gets \max_{j \in \{\max\{0, i-l\}, \dots, i\}} f(x_j)$;
\ElsIf
{$\text{``nonmonotonicity''} = (\text{``average''}, p)$}
\State
$\mu_i \gets (1-p)\mu_{i-1} + pf(x_i)$; 
\EndIf
\State
Choose $x_{i+1} \in \hyperref[algo:PGDmap]{\pgd}(x_i, \mu_i; \mathcal{E}, C, f, \ushort{\alpha}, \oshort{\alpha}, \beta, c)$;
\label{algo:PGD:PGDmap}
\State
$i \gets i+1$;
\EndWhile
\end{algorithmic}
\end{algorithm}


\begin{proposition}
\label{prop:NonmonotonePGD}
Let $(x_i)_{i \in \N}$ be a sequence generated by $\pgd$ (Algorithm~\ref{algo:PGD}) using the ``max'' rule. For every $i \in \N$, let $g(i) \in \argmax_{j \in \{\max\{0, i-l\}, \dots, i\}} f(x_j)$. Then:
\begin{enumerate}
\item $(f(x_{g(i)}))_{i \in \N}$ is monotonically nonincreasing;
\item $(x_i)_{i \in \N}$ is contained in the sublevel set~\eqref{eq:InitialSublevelSet};
\item if $x \in C$ is an accumulation point of $(x_i)_{i \in \N}$, then $(f(x_{g(i)}))_{i \in \N}$ converges to $\varphi \in [f(x), f(x_0)]$;
\item if $f$ is bounded from below and uniformly continuous on a set that contains $(x_i)_{i \in \N}$, then $(f(x_i))_{i \in \N}$ converges to $\varphi \in \R$.
\end{enumerate}
\end{proposition}

