proof.raw_tex:
\begin{proposition}
\label{prop:ProjectedTranslation}
For all $x \in C$, $v \in \mathcal{E}$, and $y \in \proj{C}{x-v}$,
\begin{align}
\label{eq:ProjectedTranslationDistance}
\norm{y-x} &\le 2 \norm{v},\\
\label{eq:ProjectedTranslationIP}
2 \ip{v}{y-x} &\le - \norm{y-x}^2,
\end{align}
and the inequalities are strict if $x \notin \proj{C}{x-v}$.
\end{proposition}

\begin{proof}
By definition of the projection, $\norm{y-(x-v)} \le \norm{x-(x-v)} = \norm{v}$ and the inequality is strict if $x \notin \proj{C}{x-v}$. Thus, on the one hand,
\begin{equation*}
\norm{y-x}
= \norm{y-(x-v)-v}
\le \norm{y-(x-v)} + \norm{-v}
\le \norm{v} + \norm{v}
= 2 \norm{v},
\end{equation*}
and, on the other hand, $\norm{y-(x-v)}^2 \le \norm{v}^2$, which is equivalent to~\eqref{eq:ProjectedTranslationIP}.
\end{proof}

\begin{proposition}
\label{prop:NonmonotonePGDAverage}
Let $(x_i)_{i \in \N}$ be a sequence generated by $\pgd$ (Algorithm~\ref{algo:PGD}) using the ``average'' rule. Then:
\begin{enumerate}
\item $(x_i)_{i \in \N}$ is contained in the sublevel set~\eqref{eq:InitialSublevelSet};
\item if  $(x_i)_{i \in \N}$ has an accumulation point, then $(f(x_i))_{i \in \N}$ and $(\mu_i)_{i\in\N}$ converge, toward the same (finite) value.
\end{enumerate}
\end{proposition}

\begin{proof}
The sequence $(\mu_i)_{i\in\N}$ is monotonically nonincreasing since, for all $i \in \N$, $f(x_i) \le \mu_{i-1}$, hence $\mu_i=(1-p)\mu_{i-1}+ pf(x_i) \le \mu_{i-1}$. Therefore, for all $i \in \N$,
\begin{equation*}
f(x_i) \le \mu_{i-1} \le \mu_{-1} = f(x_0),
\end{equation*}
meaning that $(x_i)_{i\in\N}$ is contained in the sublevel set~\eqref{eq:InitialSublevelSet}.

Let us prove the second item of the proposition. Assume that $(x_i)_{i\in\N}$ has an accumulation point $x$. Let $(x_{i_k})_{k\in\N}$ be a subsequence converging to~$x$. Observe that
\begin{equation*}
\lim_{k \to \infty} f(x_{i_k}) = f(x),
\end{equation*}
since $f$ is differentiable, and in particular continuous, at $x$.
As $(\mu_i)_{i\in\N}$ is monotonically nonincreasing, it has a limit $\varphi \in \R \cup \{-\infty\}$. For all $k \in \N$,
\begin{equation*}
f(x_{i_k}) \le \mu_{i_k-1},
\end{equation*}
and letting $k$ tend to infinity yields
\begin{equation*}
f(x) = \lim_{k\to\infty} f(x_{i_k}) \le \lim_{k\to\infty} \mu_{i_k-1} = \varphi.
\end{equation*}
In particular, $\varphi$ is finite.

Let us show that $\varphi = \liminf_{i\to\infty} f(x_i)$. Let $(x_{j_k})_{k\in\N}$ be a subsequence such that
\begin{equation*}
\lim_{k \to \infty} f(x_{j_k}) = \liminf_{i\to\infty} f(x_i).
\end{equation*}
For all $k \in \N$,
\begin{align*}
\mu_{j_k} = (1-p) \mu_{j_k-1} + p f(x_{j_k}),
\end{align*}
and letting $k$ tend to infinity yields
\begin{equation*}
\varphi = (1-p) \varphi + p \liminf_{i\to\infty} f(x_i).
\end{equation*}
As $p>0$, this implies $\varphi = \liminf_{i\to\infty} f(x_i)$ (and, in particular, $\liminf_{i\to\infty} f(x_i) > -\infty$). To conclude, we observe that, for all $k \in \N$,
\begin{equation*}
f(x_k) \le \mu_{k-1},
\end{equation*}
hence
\begin{equation*}
\limsup_{k\to\infty} f(x_k) 
\leq \lim_{k\to\infty} \mu_{k-1} = \varphi = \liminf_{k\to\infty} f(x_k).
\end{equation*}
Therefore, $(f(x_k))_{k\in\N}$ converges to $\varphi$.
\end{proof}

\begin{proposition}
\label{prop:ArbitrarySmallAlpha}
Assume that $f$ satisfies~\ref{it:continuously_diff}. Let $\ushort{x} \in C$ be non-B-stationary for~\eqref{eq:MinDiffFunctionClosedSet}, and $w \in \tancone{C}{\ushort{x}}$ be such that
\begin{equation}
\label{eq:def_w}
\ip{w}{-\nabla f(\ushort{x})} > 0.
\end{equation}
Let $\beta \in (0, 1)$. Define $\kappa \coloneq \sqrt{1 - \frac{\beta \ip{w}{-\nabla f(\ushort{x})}^2}{8 \norm{w}^2 \norm{\nabla f(\ushort{x})}^2}} \in (0, 1)$.
For every $\varepsilon \in (0, \infty)$, there exist $\alpha_{\ushort{x}} \in (0, \varepsilon]$ and $\oshort{\rho}(\alpha_{\ushort{x}}) \in (0, \infty)$ such that, for all $x \in \ball(\ushort{x}, \oshort{\rho}(\alpha_{\ushort{x}})) \cap C$ and $\alpha \in [\alpha_{\ushort{x}}, \alpha_{\ushort{x}}/\beta]$,
\begin{equation*}
\dist(x-\alpha\nabla f(x), C) \le \kappa \alpha \norm{\nabla f(x)},
\end{equation*}
which implies, for all $y \in\proj{C}{x-\alpha\nabla f(x)}$,
\begin{equation*}
\ip{\nabla f(x)}{y-x} \le - \sqrt{1-\kappa^2} \norm{\nabla f(x)} \norm{y-x}.
\end{equation*}
\end{proposition}

\begin{proof}
Let $\varepsilon \in (0, \infty)$ be fixed. We show that there exist $\alpha_{\ushort{x}} \in (0, \varepsilon]$ and $\oshort{\rho}(\alpha_{\ushort{x}}) \in (0, \infty)$ satisfying the required property.

Let $(w_i)_{i\in\N}$ be a sequence in $C$ converging to $\ushort{x}$, and $(t_i)_{i\in\N}$ be a sequence in $(0, \infty)$ such that
\begin{equation*}
\frac{w_i - \ushort{x}}{t_i} \xrightarrow{i\to\infty} w.
\end{equation*}
From the definition of $w$ in~\eqref{eq:def_w}, it holds for all $i \in \N$ large enough that
\begin{equation}
\label{eq:def_i_1}
\ip{w_i - \ushort{x}}{-\nabla f(\ushort{x})} > 0.
\end{equation}
As $\frac{1}{t_i}\frac{\norm{w_i-\ushort{x}}^2}{\ip{w_i-\ushort{x}}{-\nabla f(\ushort{x})}} \xrightarrow{i\to\infty} \frac{\norm{w}^2}{\ip{w}{-\nabla f(\ushort{x})}}$ and $t_i \xrightarrow{i\to\infty} 0$, it also holds for all $i \in \N$ large enough that
\begin{equation}
\label{eq:def_i_2}
\frac{\norm{w_i-\ushort{x}}^2}{\ip{w_i-\ushort{x}}{-\nabla f(\ushort{x})}} < \varepsilon.
\end{equation}
Similarly, it holds for all $i \in \N$ large enough that
\begin{equation}
\label{eq:def_i_3}
\frac{\ip{w_i-\ushort{x}}{-\nabla f(\ushort{x})}^2}{\norm{w_i-\ushort{x}}^2}
> \frac{\ip{w}{-\nabla f(\ushort{x})}^2}{2\norm{w}^2 }.
\end{equation}
Fix $i \in \N$ satisfying \eqref{eq:def_i_1}, \eqref{eq:def_i_2}, and \eqref{eq:def_i_3}.
Pick $\alpha_{\ushort{x}}$ such that
\begin{equation*}
\frac{\alpha_{\ushort{x}}}{2}
< \frac{\norm{w_i-\ushort{x}}^2}{\ip{w_i-\ushort{x}}{-\nabla f(\ushort{x})}}
< \alpha_{\ushort{x}}
< \varepsilon.
\end{equation*}
Since $\nabla f$ is continuous at $\ushort{x}$, there exists $\rho_0 \in (0, \infty)$ such that, for all $x \in \ball[\ushort{x}, \rho_0] \cap C$,
\begin{subequations}
\begin{gather}
\label{eq:def_rho0_1}
\ip{w_i-\ushort{x}}{-\nabla f(x)} > 0,\\
\label{eq:def_rho0_2}
\frac{\alpha_{\ushort{x}}}{2}
< \frac{\norm{w_i-\ushort{x}}^2}{\ip{w_i-\ushort{x}}{-\nabla f(x)}}
< \alpha_{\ushort{x}},\\
\label{eq:def_rho0_3}
\frac{\ip{w_i-\ushort{x}}{-\nabla f(x)}^2}{\norm{w_i-\ushort{x}}^2 \norm{\nabla f(x)}^2}
> \frac{\ip{w}{-\nabla f(\ushort{x})}^2}{2\norm{w}^2 \norm{\nabla f(\ushort{x})}^2}.
\end{gather}
\end{subequations}
We now establish the first inequality we have to prove: for an adequate value of $\oshort{\rho}(\alpha_{\ushort{x}})$, it holds for all $x \in \ball(\ushort{x}, \oshort{\rho}(\alpha_{\ushort{x}})) \cap C$ and $\alpha \in [\alpha_{\ushort{x}}, \alpha_{\ushort{x}}/\beta]$ that
\begin{equation*}
\norm{x - \alpha \nabla f(x) - y} \le \kappa \alpha \norm{\nabla f(x)}\quad
\forall y \in \proj{C}{x-\alpha\nabla f(x)},
\end{equation*}
which is equivalent to $\dist(x-\alpha\nabla f(x), C) \le \kappa \alpha \norm{\nabla f(x)}$.

For the moment, let $\oshort{\rho}(\alpha_{\ushort{x}}) \in (0, \rho_0]$ be arbitrary. For all $x \in \ball(\ushort{x}, \oshort{\rho}(\alpha_{\ushort{x}})) \cap C$, $\alpha \in [\alpha_{\ushort{x}}, \alpha_{\ushort{x}}/\beta]$, and $y \in \proj{C}{x-\alpha\nabla f(x)}$,
\begin{align*}
\norm{x - \alpha \nabla f(x) - y}^2
&\le \norm{x - \alpha \nabla f(x) - w_i}^2 \\
&= \norm{\ushort{x}-\alpha \nabla f(x) - w_i}^2 + 2 \ip{\ushort{x}-x}{\alpha \nabla f(x) + w_i-\ushort{x}} + \norm{\ushort{x}-x}^2 \\
&\le \norm{\ushort{x}-\alpha \nabla f(x) - w_i}^2 \\
&\qquad + 2 \oshort{\rho}(\alpha_{\ushort{x}}) \left(\alpha \norm{\nabla f(x)} + \norm{w_i-\ushort{x}}\right) + \oshort{\rho}(\alpha_{\ushort{x}})^2 \\
&\le \norm{\ushort{x}-\alpha \nabla f(x) - w_i}^2 \\
&\qquad + 2 \oshort{\rho}(\alpha_{\ushort{x}}) \left(\alpha \max_{z \in \ball[\ushort{x}, \rho_0] \cap C} \norm{\nabla f(z)} + \norm{w_i-\ushort{x}}\right) + \oshort{\rho}(\alpha_{\ushort{x}})^2 \\
&= \alpha^2 \norm{\nabla f(x)}^2 -2 \alpha \ip{w_i-\ushort{x}}{-\nabla f(x)} + \norm{w_i-\ushort{x}}^2 \\
&\qquad + 2 \oshort{\rho}(\alpha_{\ushort{x}}) \left(\alpha \max_{z \in \ball[\ushort{x}, \rho_0] \cap C} \norm{\nabla f(z)} + \norm{w_i-\ushort{x}}\right) + \oshort{\rho}(\alpha_{\ushort{x}})^2 \\
&\le \alpha^2 \norm{\nabla f(x)}^2 - \alpha \ip{w_i-\ushort{x}}{-\nabla f(x)} \\
&\qquad + 2 \oshort{\rho}(\alpha_{\ushort{x}}) \left(\frac{\alpha_{\ushort{x}}}{\beta} \max_{z \in \ball[\ushort{x}, \rho_0] \cap C} \norm{\nabla f(z)} + \norm{w_i-\ushort{x}}\right)
+ \oshort{\rho}(\alpha_{\ushort{x}})^2,
\end{align*}
where the last inequality follows from \eqref{eq:def_rho0_2} and the fact that $\alpha_{\ushort{x}} \le \alpha \le \frac{\alpha_{\ushort{x}}}{\beta}$.
Now, choose $\oshort{\rho}(\alpha_{\ushort{x}}) \in (0, \rho_0]$ small enough to ensure
\begin{align*}
&2 \oshort{\rho}(\alpha_{\ushort{x}}) \left(\frac{\alpha_{\ushort{x}}}{\beta} \max_{z \in \ball[\ushort{x}, \rho_0] \cap C} \norm{\nabla f(z)} + \norm{w_i-\ushort{x}}\right) + \oshort{\rho}(\alpha_{\ushort{x}})^2 \\
&\le \frac{\alpha_{\ushort{x}}}{2} \min_{z \in \ball[\ushort{x}, \rho_0] \cap C} \ip{w_i-\ushort{x}}{-\nabla f(z)}.
\end{align*}
Note that the right-hand side of this inequality is positive, from \eqref{eq:def_rho0_1}.
Combining this definition with the previous inequality, we arrive at
\begin{align*}
\norm{x - \alpha \nabla f(x) - y}^2
&\le \alpha^2 \norm{\nabla f(x)}^2 - \frac{\alpha}{2} \ip{w_i-\ushort{x}}{-\nabla f(x)}\\
&= \alpha^2 \norm{\nabla f(x)}^2 \left(1 - \frac{\ip{w_i-\ushort{x}}{-\nabla f(x)}}{2 \alpha \norm{\nabla f(x)}^2}\right)\\
&\le \alpha^2 \norm{\nabla f(x)}^2 \left(1 - \frac{\beta \ip{w_i-\ushort{x}}{-\nabla f(x)}}{2 \alpha_{\ushort{x}} \norm{\nabla f(x)}^2}\right)
\text{ as $\alpha \le \frac{\alpha_{\ushort{x}}}{\beta}$}\\
&\le \alpha^2 \norm{\nabla f(x)}^2 \left(1 - \frac{\beta \ip{w_i-\ushort{x}}{-\nabla f(x)}^2}{4 \norm{w_i-\ushort{x}}^2 \norm{\nabla f(x)}^2}\right)
\text{ from~\eqref{eq:def_rho0_2}}\\
&\le \alpha^2 \norm{\nabla f(x)}^2 \left(1 - \frac{\beta \ip{w}{-\nabla f(\ushort{x})}^2}{8 \norm{w}^2 \norm{\nabla f(\ushort{x})}^2}\right)
\text{ from~\eqref{eq:def_rho0_3}}\\
&= \kappa^2 \alpha^2 \norm{\nabla f(x)}^2.
\end{align*}
Thus, for all $x \in \ball(\ushort{x}, \oshort{\rho}(\alpha_{\ushort{x}})) \cap C$, $\alpha \in [\alpha_{\ushort{x}}, \alpha_{\ushort{x}}/\beta]$, and $y \in \proj{C}{x-\alpha\nabla f(x)}$,
\begin{equation*}
\norm{x - \alpha \nabla f(x) - y} \le \kappa \alpha \norm{\nabla f(x)}.
\end{equation*}
To conclude, we show that this inequality implies
\begin{equation}
\label{eq:ip_xy_nabla}
\ip{\frac{y-x}{\norm{y-x}}}{\frac{\nabla f(x)}{\norm{\nabla f(x)}}} \le - \sqrt{1-\kappa^2}.
\end{equation}
Indeed, defining $\theta \in \R$ such that $\ip{\frac{y-x}{\norm{y-x}}}{\frac{\nabla f(x)}{\norm{\nabla f(x)}}} = \cos(\theta)$, we have
\begin{equation*}
\norm{y-x}^2 + 2 \alpha \norm{\nabla f(x)} \norm{y-x} \cos(\theta) + \alpha^2 \norm{\nabla f(x)}^2
\le \alpha^2 \kappa^2 \norm{\nabla f(x)}^2.
\end{equation*}
This already shows that $\cos(\theta) < 0$. In addition, minimizing the left-hand side over all possible values of $\norm{y-x}$, we get
\begin{equation*}
- \alpha^2 \norm{\nabla f(x)}^2 \cos^2(\theta) + \alpha^2 \norm{\nabla f(x)}^2
\le \alpha^2 \kappa^2 \norm{\nabla f(x)}^2,
\end{equation*}
hence $\cos^2(\theta) \ge 1 - \kappa^2$, which establishes \eqref{eq:ip_xy_nabla}.
\end{proof}

\begin{proposition}
\label{prop:AcceptedStep}
Let $\ushort{\alpha} \in (0, \infty)$ and $\beta, c \in (0, 1)$.
Assume that $f$ satisfies~\ref{it:continuously_diff}. Let $\ushort{x} \in C$ be non-B-stationary for~\eqref{eq:MinDiffFunctionClosedSet}.
There exist $\alpha_{\ushort{x}} \in (0, \ushort{\alpha}]$ and $\rho \in (0, \infty)$ such that, for all $x \in \ball(\ushort{x}, \rho) \cap C$, $\alpha \in [\alpha_{\ushort{x}}, \alpha_{\ushort{x}}/\beta]$, and $y \in \proj{C}{x-\alpha\nabla f(x)}$,
\begin{equation*}
f(y) < f(x) + c \ip{\nabla f(x)}{y-x}.
\end{equation*}
\end{proposition}

\begin{proof}
Define $\kappa$ as in Proposition~\ref{prop:ArbitrarySmallAlpha}. Let $\delta \in (0, \infty)$ be small enough to ensure
\begin{subequations}
\begin{align}
\label{eq:def_alpha_x_small1}
\sup_{y \in \ball\left[\ushort{x}, \frac{7\delta}{2\beta}\norm{\nabla f(\ushort{x})}\right] \cap C \setminus \{\ushort{x}\}}
\frac{|f(y)-f(\ushort{x}) - \ip{\nabla f(\ushort{x})}{y-\ushort{x}}|}{\norm{y-\ushort{x}}}
&< \frac{(1-c)\sqrt{1-\kappa^2}\norm{\nabla f(\ushort{x})}}{4\left(1 + \frac{8}{3(1-\kappa)}\right)},\\
\label{eq:def_alpha_x_small2}
\sup_{y \in \ball\left[\ushort{x}, \frac{7\delta}{2\beta}\norm{\nabla f(\ushort{x})}\right] \cap C}
\norm{\nabla f(y)-\nabla f(\ushort{x})}
&< \frac{(1-c)\sqrt{1-\kappa^2}}{4} \norm{\nabla f(\ushort{x})}.
\end{align}
\end{subequations}
These inequalities are satisfied by all $\delta$ small enough, from the definition of the gradient for the first one, and because the gradient is continuous at $\ushort{x}$ for the second one.

Then, define $\varepsilon \coloneq \min\left\{\ushort{\alpha}, \delta\right\}$ and let $\alpha_{\ushort{x}} \in (0, \varepsilon]$ and $\oshort{\rho}(\alpha_{\ushort{x}})\in(0,\infty)$ be given by Proposition~\ref{prop:ArbitrarySmallAlpha}.
Define
\begin{equation*}
\rho \coloneq \min\left\{\oshort{\rho}(\alpha_{\ushort{x}}), \alpha_{\ushort{x}} \norm{\nabla f(\ushort{x})}\right\}.
\end{equation*}
Note that, for all $x \in \ball(\ushort{x}, \rho) \cap C$,
\begin{equation*}
\norm{x-\ushort{x}}
< \rho \le \alpha_{\ushort{x}} \norm{\nabla f(\ushort{x})}
< \frac{7\alpha_{\ushort{x}}}{2\beta} \norm{\nabla f(\ushort{x})}
\leq \frac{7\delta }{2\beta} \norm{\nabla f(\ushort{x})},
\end{equation*}
so that from~\eqref{eq:def_alpha_x_small2}, $\norm{\nabla f(x)-\nabla f(\ushort{x})} < \frac{\norm{\nabla f(\ushort{x})}}{4}$, which implies
\begin{align}
\nonumber
\frac{3}{4} \norm{\nabla f(\ushort{x})}
& < \norm{\nabla f(\ushort{x})}-\norm{\nabla f(x)-\nabla f(\ushort{x})} \\
& \le \norm{\nabla f(x)} \nonumber\\
& \le \norm{\nabla f(\ushort{x})}+\norm{\nabla f(x)-\nabla f(\ushort{x})} \nonumber\\
& < \frac{5}{4} \norm{\nabla f(\ushort{x})}.
\label{eq:nablas_ushortx_x}
\end{align}
For all $x \in \ball(\ushort{x}, \rho) \cap C$, $\alpha \in [\alpha_{\ushort{x}}, \alpha_{\ushort{x}}/\beta]$, and $y \in \proj{C}{x-\alpha\nabla f(x)}$,
\begin{align}
f(y)
&= f(x) + \ip{\nabla f(\ushort{x})}{y-x} \nonumber\\
&\qquad + \left(f(\ushort{x}) - f(x) - \ip{\nabla f(\ushort{x})}{\ushort{x}-x}\right) \nonumber\\
&\qquad + \left(f(y) - f(\ushort{x}) - \ip{\nabla f(\ushort{x})}{y-\ushort{x}}\right) \nonumber\\
&\le f(x) + \ip{\nabla f(\ushort{x})}{y-x} +
\frac{(1-c)\sqrt{1-\kappa^2}\norm{\nabla f(\ushort{x})}}{4\left(1 + \frac{8}{3(1-\kappa)}\right)} \left(\norm{\ushort{x}-x} + \norm{y-\ushort{x}}\right),
\label{eq:UpperBoundfDiffGrad}
\end{align}
where the inequality follows from \eqref{eq:def_alpha_x_small1}. Observe that
\begin{align*}
\norm{y-\ushort{x}}
&\le \norm{y-x} + \norm{x-\ushort{x}} \\
&\le 2 \alpha \norm{\nabla f(x)} + \rho
\text{ from \eqref{eq:ProjectedTranslationDistance}}\\
&\le \frac{2 \alpha_{\ushort{x}}}{\beta} \norm{\nabla f(x)}
+ \alpha_{\ushort{x}} \norm{\nabla f(\ushort{x})} \\
&< \frac{5\alpha_{\ushort{x}}}{2\beta} \norm{\nabla f(\ushort{x})}
+ \alpha_{\ushort{x}} \norm{\nabla f(\ushort{x})} 
\text{ from \eqref{eq:nablas_ushortx_x}} \\
&\le \frac{7\alpha_{\ushort{x}}}{2\beta} \norm{\nabla f(\ushort{x})}.
\end{align*}
We continue from \eqref{eq:UpperBoundfDiffGrad}:
\begin{align*}
f(y)
& \le f(x) + \ip{\nabla f(\ushort{x})}{y-x} +
\frac{(1-c)\sqrt{1-\kappa^2}\norm{\nabla f(\ushort{x})}}{
4\left(1 + \frac{8}{3(1-\kappa)}\right)} \left(2\norm{\ushort{x}-x} + \norm{y-x}\right) \\
&\overset{\text{(a)}}{<} f(x) + \ip{\nabla f(\ushort{x})}{y-x}
+ \frac{(1-c)\sqrt{1-\kappa^2}\norm{\nabla f(\ushort{x})}}{4} \norm{y-x} \\
&\le f(x) + \ip{\nabla f(x)}{y-x} + \norm{\nabla f(\ushort{x})-\nabla f(x)} \norm{y-x} \\
&\qquad + \frac{(1-c)\sqrt{1-\kappa^2}\norm{\nabla f(\ushort{x})}}{4} \norm{y-x} \\
&\le f(x) + \ip{\nabla f(x)}{y-x} + \frac{(1-c)\sqrt{1-\kappa^2}\norm{\nabla f(\ushort{x})}}{2} \norm{y-x}
\text{ from~\eqref{eq:def_alpha_x_small2}}\\
&< f(x) + \ip{\nabla f(x)}{y-x} + (1-c)\sqrt{1-\kappa^2} \norm{\nabla f(x)}\norm{y-x}
\text{ from~\eqref{eq:nablas_ushortx_x}}\\
&\le f(x) + \ip{\nabla f(x)}{y-x} - (1-c) \ip{\nabla f(x)}{y-x}
\text{ from Proposition~\ref{prop:ArbitrarySmallAlpha}}\\
&= f(x) + c \ip{\nabla f(x)}{y-x}.
\end{align*}
Inequality (a) is true because
\begin{align*}
\norm{y-x}
&\ge \alpha \norm{\nabla f(x)} - \norm{x-\alpha \nabla f(x)-y}
\text{ by the triangle inequality}\\
&= \alpha \norm{\nabla f(x)} - \dist(x-\alpha\nabla f(x), C) \\
&\ge (1-\kappa) \alpha \norm{\nabla f(x)}
\text{ from Proposition~\ref{prop:ArbitrarySmallAlpha}}\\
&\ge \frac{3}{4} (1-\kappa) \rho
\text{ from~\eqref{eq:nablas_ushortx_x}, the definition of $\rho$, and $\alpha_{\ushort{x}} \le \alpha$}\\
&> \frac{3}{4} (1-\kappa) \norm{x-\ushort{x}}.
\end{align*}
\end{proof}

\begin{proposition}
\label{prop:convergence_ik}
Let $(x_i)_{i \in \N}$ be a sequence generated by $\pgd$ (Algorithm~\ref{algo:PGD}), under~\ref{it:continuously_diff}, and $x$ be an accumulation point.
Then, for every subsequence $(x_{i_k})_{k\in\N}$ converging to $x$, the sequence $(x_{i_k+1})_{k\in\N}$ also converges to $x$.
\end{proposition}

\begin{proof}
Let $(x_{i_k})_{k\in\N}$ be a subsequence converging to $x$. We show that $(x_{i_k+1})_{k\in\N}$ also converges to $x$.

If the nonmonotonicity rule is set to ``average'', this is a direct consequence of Proposition~\ref{prop:NonmonotonePGDAverage}. Indeed, for all $i \in \N$, from~\eqref{eq:KanzowMehlitzDecay},
\begin{equation*}
f(x_{i+1}) \le \mu_i - \frac{c}{2 \oshort{\alpha}} \norm{x_{i+1}-x_i}^2 \le \mu_i.    
\end{equation*}
From Proposition~\ref{prop:NonmonotonePGDAverage}, $(f(x_{i+1}))_{i\in\N}$ and $(\mu_i)_{i\in\N}$ converge to the same limit. Therefore,
\begin{equation*}
 \left(\mu_i - \frac{c}{2 \oshort{\alpha}} \norm{x_{i+1}-x_i}^2\right)_{i\in\N}
\end{equation*}
also converges to this limit.
This implies that $(\norm{x_{i+1}-x_i})_{i\in\N}$ converges to $0$, hence $(\norm{x_{i_k+1}-x_{i_k}})_{k\in\N}$ converges to $0$, and $(x_{i_k+1})_{k\in\N}$ converges to the same limit as $(x_{i_k})_{k\in\N}$, that is, $x$.

Now, let us consider the ``max'' rule case. It suffices to show that $x$ is an accumulation point of every subsequence of $(x_{i_k+1})_{k\in\N}$. Thus, we show the following: for every subsequence $(i_{j_k})_{k\in\N}$ of $(i_k)_{k\in\N}$, there exists a subsequence of $(x_{i_{j_k}+1})_{k\in\N}$ that converges to $x$.
Let $(i_{j_k})_{k\in\N}$ be a subsequence of $(i_k)_{k\in\N}$.
For all $i \in \N$, let $g(i) \in \argmax_{j \in \{\max\{0, i-l\}, \dots, i\}} f(x_j)$, as in Proposition~\ref{prop:NonmonotonePGD}. By the third statement of Proposition~\ref{prop:NonmonotonePGD}, the sequence $(f(x_{g(i)}))_{i\in\N}$ converges to $\varphi \in [f(x), f(x_0)]$.
For every $k \in \N$, letting $\alpha_{i_{j_k}} \in (0, \oshort{\alpha}]$ be the number such that $x_{i_{j_k}+1} \in \proj{C}{x_{i_{j_k}} - \alpha_{i_{j_k}} \nabla f(x_{i_{j_k}})}$, by \eqref{eq:ProjectedTranslationDistance},
\begin{equation*}
\norm{x_{i_{j_k}+1}-x_{i_{j_k}}}
\le 2 \alpha_{i_{j_k}} \norm{\nabla f(x_{i_{j_k}})}
\le 2 \oshort{\alpha} \norm{\nabla f(x_{i_{j_k}})}.
\end{equation*}
Thus, since $(x_{i_{j_k}})_{k\in\N}$ is bounded and $\nabla f$ is locally bounded (as it is continuous), the sequence $(x_{i_{j_k}+1})_{k\in\N}$ is bounded. If we replace $(i_{j_k})_{k\in\N}$ with a subsequence, we can assume that $(x_{i_{j_k}+1})_{k\in\N}$ converges.

Iterating the reasoning, we can assume that $(x_{i_{j_k}+s})_{k\in\N}$ converges to some $x^{s}\in C$ for every $s \in \{0, \dots, l+1\}$. By definition of $x$, $x^{0}=x$.

Observe that, from the continuity of $f$,
\begin{align*}
f(x_{g(i_{j_k}+l+1)})
&= \max\{f(x_{i_{j_k}+1}), \dots, f(x_{i_{j_k}+l+1})\} \\
&\to \max\{f(x^{1}), \dots, f(x^{l+1})\}
\text{ when } k \to \infty.
\end{align*}
In particular, there exists $s_1 \in \{1, \dots, l+1\}$ such that
\begin{equation}
\label{eq:def_s_1}
f(x^{s_1}) = \varphi.
\end{equation}
Let $s_1$ be the smallest such integer.
For all $k \in \N$, from the condition in line~\ref{algo:PGDmap:NonmonotoneArmijoCondition} of Algorithm~\ref{algo:PGDmap} and~\eqref{eq:KanzowMehlitzDecay},
\begin{align*}
f(x_{i_{j_k}+s_1})
&\le f(x_{g(i_{j_k}+s_1-1)}) - \frac{c}{2\oshort{\alpha}} \norm{x_{i_{j_k}+s_1}-x_{i_{j_k}+s_1-1}}^2,
\end{align*}
and letting $k$ tend to infinity yields
\begin{equation*}
\varphi
= f(x^{s_1})
\le \varphi - \frac{c}{2\oshort{\alpha}} \norm{x^{s_1}-x^{s_1-1}}^2.
\end{equation*}
Consequently, $x^{s_1} = x^{s_1-1}$. In particular, $f(x^{s_1-1}) =f(x^{s_1}) = \varphi$. Therefore, $s_1=1$, otherwise it would not be the smallest integer satisfying \eqref{eq:def_s_1}. The equality $x^{s_1} = x^{s_1-1}$ then reduces to $x^{1}=x^{0}=x$ and, when $k \to \infty$,
\begin{equation*}
x_{i_{j_k}+1} \to x^{1} = x.
\end{equation*}
\end{proof}

\subsection{Third part: proof of Theorem~\ref{thm:PGDaccumulatesAtBStationaryPoints}}
\label{subsec:proof_accumulates}
Let $\ushort{x}$ be an accumulation point of $(x_i)_{i\in\N}$. Assume, for the sake of contradiction, that $\ushort{x}$ is not B-stationary for~\eqref{eq:MinDiffFunctionClosedSet}. Let $(x_{i_k})_{k\in\N}$ be a subsequence converging to $\ushort{x}$.

Let $\alpha_{\ushort{x}}$ and $\rho$ be as in Proposition~\ref{prop:AcceptedStep}. For all $k \in \N$ large enough, $x_{i_k} \! \in \ball(\ushort{x}, \rho) \cap C$. Thus, when Algorithm~\ref{algo:PGDmap} is called at point $x_{i_k}$, the condition in line~\ref{algo:PGDmap:NonmonotoneArmijoCondition} stops being fulfilled for some $\alpha_{i_k} \ge \alpha_{\ushort{x}}$, meaning that
\begin{equation*}
x_{i_k+1} \in \proj{C}{x_{i_k}-\alpha_{i_k} \nabla f(x_{i_k})}
\text{ for some } \alpha_{i_k} \in [\alpha_{\ushort{x}}, \oshort{\alpha}].
\end{equation*}
Replacing $(i_k)_{k\in\N}$ with a subsequence if necessary, we can assume that $(\alpha_{i_k})_{k\in\N}$ converges to some $\alpha_{\lim} \in [\alpha_{\ushort{x}}, \oshort{\alpha}]$.

For all $k \in \N$, we have
\begin{equation*}
\norm{x_{i_k} - \alpha_{i_k} \nabla f(x_{i_k}) - x_{i_k+1}}
= \dist(x_{i_k} - \alpha_{i_k} \nabla f(x_{i_k}), C),
\end{equation*}
and since the distance to a nonempty closed set is a continuous function, we can take this equality to the limit. We use the fact that $x_{i_k+1} \to \ushort{x}$ when $k \to \infty$, from Proposition~\ref{prop:convergence_ik}. This yields
\begin{equation*}
\norm{\alpha_{\lim} \nabla f(\ushort{x})}
= \dist(\ushort{x} - \alpha_{\lim}\nabla f(\ushort{x}), C),
\end{equation*}
which means that $\ushort{x} \in \proj{C}{\ushort{x} - \alpha_{\lim}\nabla f(\ushort{x})}$. In particular, $-\nabla f(\ushort{x}) \in \proxnorcone{C}{\ushort{x}} \subseteq \regnorcone{C}{\ushort{x}}$, which contradicts our assumption that $\ushort{x}$ is not B-stationary for~\eqref{eq:MinDiffFunctionClosedSet}. We have therefore proven that every accumulation point is B-stationary.

Finally, if $(x_i)_{i\in\N}$ has an isolated accumulation point, then the sequence $(x_i)_{i\in\N}$ converges, from Proposition~\ref{prop:convergence_ik} and \cite[Lemma~4.10]{MoreSorensen}.

