\begin{proposition}
\label{prop:NonmonotonePGDAverage}
Let $(x_i)_{i \in \N}$ be a sequence generated by $\pgd$ (Algorithm~\ref{algo:PGD}) using the ``average'' rule. Then:
\begin{enumerate}
\item $(x_i)_{i \in \N}$ is contained in the sublevel set~\eqref{eq:InitialSublevelSet};

\begin{proof}
The sequence $(\mu_i)_{i\in\N}$ is monotonically nonincreasing since, for all $i \in \N$, $f(x_i) \le \mu_{i-1}$, hence $\mu_i=(1-p)\mu_{i-1}+ pf(x_i) \le \mu_{i-1}$. Therefore, for all $i \in \N$,
\begin{equation*}
f(x_i) \le \mu_{i-1} \le \mu_{-1} = f(x_0),
\end{equation*}
meaning that $(x_i)_{i\in\N}$ is contained in the sublevel set~\eqref{eq:InitialSublevelSet}.

Let us prove the second item of the proposition. Assume that $(x_i)_{i\in\N}$ has an accumulation point $x$. Let $(x_{i_k})_{k\in\N}$ be a subsequence converging to~$x$. Observe that
\begin{equation*}
\lim_{k \to \infty} f(x_{i_k}) = f(x),
\end{equation*}
since $f$ is differentiable, and in particular continuous, at $x$.
As $(\mu_i)_{i\in\N}$ is monotonically nonincreasing, it has a limit $\varphi \in \R \cup \{-\infty\}$. For all $k \in \N$,
\begin{equation*}
f(x_{i_k}) \le \mu_{i_k-1},
\end{equation*}
and letting $k$ tend to infinity yields
\begin{equation*}
f(x) = \lim_{k\to\infty} f(x_{i_k}) \le \lim_{k\to\infty} \mu_{i_k-1} = \varphi.
\end{equation*}
In particular, $\varphi$ is finite.

Let us show that $\varphi = \liminf_{i\to\infty} f(x_i)$. Let $(x_{j_k})_{k\in\N}$ be a subsequence such that
\begin{equation*}
\lim_{k \to \infty} f(x_{j_k}) = \liminf_{i\to\infty} f(x_i).
\end{equation*}
For all $k \in \N$,
\begin{align*}
\mu_{j_k} = (1-p) \mu_{j_k-1} + p f(x_{j_k}),
\end{align*}
and letting $k$ tend to infinity yields
\begin{equation*}
\varphi = (1-p) \varphi + p \liminf_{i\to\infty} f(x_i).
\end{equation*}
As $p>0$, this implies $\varphi = \liminf_{i\to\infty} f(x_i)$ (and, in particular, $\liminf_{i\to\infty} f(x_i) > -\infty$). To conclude, we observe that, for all $k \in \N$,
\begin{equation*}
f(x_k) \le \mu_{k-1},
\end{equation*}
hence
\begin{equation*}
\limsup_{k\to\infty} f(x_k) 
\leq \lim_{k\to\infty} \mu_{k-1} = \varphi = \liminf_{k\to\infty} f(x_k).
\end{equation*}
Therefore, $(f(x_k))_{k\in\N}$ converges to $\varphi$.
\end{proof}

