\begin{theorem}
\label{thm:PGDaccumulatesAtBStationaryPoints}
Let $(x_i)_{i \in \N}$ be a sequence generated by $\pgd$ (Algorithm~\ref{algo:PGD}), under~\ref{it:continuously_diff}. Then, all accumulation points of $(x_i)_{i \in \N}$ are B-stationary for~\eqref{eq:MinDiffFunctionClosedSet}.
If, moreover, $(x_i)_{i \in \N}$ has an isolated accumulation point, then $(x_i)_{i \in \N}$ converges.
\end{theorem}

\subsection{Third part: proof of Theorem~\ref{thm:PGDaccumulatesAtBStationaryPoints}}
\label{subsec:proof_accumulates}
Let $\ushort{x}$ be an accumulation point of $(x_i)_{i\in\N}$. Assume, for the sake of contradiction, that $\ushort{x}$ is not B-stationary for~\eqref{eq:MinDiffFunctionClosedSet}. Let $(x_{i_k})_{k\in\N}$ be a subsequence converging to $\ushort{x}$.

Let $\alpha_{\ushort{x}}$ and $\rho$ be as in Proposition~\ref{prop:AcceptedStep}. For all $k \in \N$ large enough, $x_{i_k} \! \in \ball(\ushort{x}, \rho) \cap C$. Thus, when Algorithm~\ref{algo:PGDmap} is called at point $x_{i_k}$, the condition in line~\ref{algo:PGDmap:NonmonotoneArmijoCondition} stops being fulfilled for some $\alpha_{i_k} \ge \alpha_{\ushort{x}}$, meaning that
\begin{equation*}
x_{i_k+1} \in \proj{C}{x_{i_k}-\alpha_{i_k} \nabla f(x_{i_k})}
\text{ for some } \alpha_{i_k} \in [\alpha_{\ushort{x}}, \oshort{\alpha}].
\end{equation*}
Replacing $(i_k)_{k\in\N}$ with a subsequence if necessary, we can assume that $(\alpha_{i_k})_{k\in\N}$ converges to some $\alpha_{\lim} \in [\alpha_{\ushort{x}}, \oshort{\alpha}]$.

For all $k \in \N$, we have
\begin{equation*}
\norm{x_{i_k} - \alpha_{i_k} \nabla f(x_{i_k}) - x_{i_k+1}}
= \dist(x_{i_k} - \alpha_{i_k} \nabla f(x_{i_k}), C),
\end{equation*}
and since the distance to a nonempty closed set is a continuous function, we can take this equality to the limit. We use the fact that $x_{i_k+1} \to \ushort{x}$ when $k \to \infty$, from Proposition~\ref{prop:convergence_ik}. This yields
\begin{equation*}
\norm{\alpha_{\lim} \nabla f(\ushort{x})}
= \dist(\ushort{x} - \alpha_{\lim}\nabla f(\ushort{x}), C),
\end{equation*}
which means that $\ushort{x} \in \proj{C}{\ushort{x} - \alpha_{\lim}\nabla f(\ushort{x})}$. In particular, $-\nabla f(\ushort{x}) \in \proxnorcone{C}{\ushort{x}} \subseteq \regnorcone{C}{\ushort{x}}$, which contradicts our assumption that $\ushort{x}$ is not B-stationary for~\eqref{eq:MinDiffFunctionClosedSet}. We have therefore proven that every accumulation point is B-stationary.

Finally, if $(x_i)_{i\in\N}$ has an isolated accumulation point, then the sequence $(x_i)_{i\in\N}$ converges, from Proposition~\ref{prop:convergence_ik} and \cite[Lemma~4.10]{MoreSorensen}.

